@startuml

class Employee {
  +name : string
  +socialSecurityNumber : string
}

class Driver extends Employee {
}

class Planner extends Employee {
  +username : string
  +password : string
}

class AdministrativeStaff extends Employee {
  +username : string
  +password : string
  +fieldOfActivity : string
}

class Customer {
  +name : string
  +billingAddress : string
}

class PartnerCompany {
  +name : string
  +address : string
}

class Vehicle {
  +licensePlateNumber : string
  +mileage : int
}

class RefrigeratedTruck extends Vehicle {}
class SmallVan extends Vehicle {}
class LoadingPlatform extends Vehicle {}
class BoxTruck extends Vehicle {}

class Repair {
  +duration : string
  +cost : float
}

class RepairShop {
  +name : string
  +address : string
}

class Order {
  +packageSize : string
  +comment : string
  +startTime : datetime
  +finishTime : datetime
  +pickupAddress : string
  +deliveryAddress : string
}

Employee "0..*" -- "1" Repair : takes vehicle to :
Repair "0..*" -- "1" Vehicle : is performed on :
Repair "0..*" -- "1" RepairShop : occurs at :

Driver "0..1" -- "0..*" Order : is assigned to :
Driver "0..*" -- "0..*" Order : completes :
Vehicle "0..*" -- "0..*" Order : is used for :
Planner "0..*" -- "0..*" Order : assigns :
Customer "1" -- "0..*" Order : is client of :
Order "0..*" -- "0..1" Customer : placed with :
Order "0..*" -- "0..1" PartnerCompany : placed with :

@enduml

